 "content": "def transform(grid):
    """Move each 4 down one row; the lowest 4 above the 2-bar fans upward diagonally."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    # Keep the separator and other non-4 cells as they are.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                out[r][c] = grid[r][c]

    separators = [r for r, row in enumerate(grid)
                  if row and all(value == 2 for value in row)]
    sep = separators[0] if separators else h
    sources = [(r, c) for r in range(sep) for c in range(w) if grid[r][c] == 4]

    # All markers advance one row downward (clamped at the bottom edge).
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                out[min(r + 1, h - 1)][c] = 4

    # The marker nearest the separator casts a widening diagonal fan upward.
    if sources:
        r, c = max(sources)
        apex = min(r + 1, h - 1)
        for distance in range(h):
            rr = apex - distance
            if rr < 0:
                break
            for cc in (c - distance, c + distance):
                if 0 <= cc < w:
                    out[rr][cc] = 4
    return out
